// features() returns a temporary vector
std::vector<bool> features(const Widget&);

Widget w;

// Correctly and safely deduce a bool
// 1. features(w)[5] returns a std::vector<bool>::reference proxy.
// 2. static_cast<bool> calls the proxy's conversion operator to get a bool value.
// 3. auto deduces the type of highPriority to be bool.
// 4. The temporary proxy and vector are safely discarded.
auto highPriority = static_cast<bool>(features(w)[5]);

processWidget(w, highPriority); // Safe, highPriority is a bool
